{
  "selections": [
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '약한 사람이 되면 구체적으로 어떤 일이 일어날 것 같은지'를 묻고 있는데, 이 가설은 정확히 기준을 낮추면 결과가 무너지고 사람들이 자신의 한계를 알게 될 것이라는 공포를 담고 있어 상담사의 질문과 직접적으로 연결됨. 배경에서는 아버지가 98점에도 '2점은 왜 틀렸냐'고 추궁한 경험이 이 공포의 기원을 설명함."
    },
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '뭘 인정하면 약한 사람이 되는 것 같다'고 한 것은 '무엇이든 충분하지 않다'는 핵심신뢰의 작동과 직결됨. 상담사가 그 공포의 내용을 구체화하려는 질문에 대해, 이 신념이 '약함=충분하지 않음'이라는 등식을 만들어내는 근거가 됨."
    },
    {
      "trait_id": "/core_belief/schema_definition",
      "background_ids": ["/childhood_data"],
      "relevance": "'약한 사람이 되는 것'을 두려워하는 것이 곧 비난을 피하기 위해 높은 기준을 충족해야 한다는 강박의 표현이며, 상담사의 질문은 이 강박이 깨졌을 때의 시나리오를 탐색하는 것이므로 직접 관련됨."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/situations/2"],
      "relevance": "내담자가 '약한 사람'이 되는 것을 회피하는 것은 '쉬는 것은 자격을 갖춘 다음의 일'이라는 규칙의 방어적 작동이며, 상황 사례에서는 남편의 드라이브 제안을 거절하면서 '도망치는 것'이라고 자기 합리화한 패턴이 이 규칙의 실례임."
    },
    {
      "trait_id": "/core_belief/young_domain",
      "background_ids": ["/situations/3"],
      "relevance": "'약한 사람이 되는 것'에 대한 공포는 과잉경계·억제 영역의 핵심 정서이며, 설명회 설문 29장 만족 중 1장의 '다소 빨랐다'에 집착한 사례는 경계가 풀리는 순간 비난이 올 것이라는 공포가 작동한 장면임."
    }
  ]
}

